import math
import numpy as np
from scipy.optimize import least_squares

def _features(row):
    u = float(row['u_now'])
    s = float(row['s_grad'])
    return u, s

def _model(row, p):
    vmax, rho, c_loc = p
    u, s = _features(row)
    un = u  # characteristic tau scale is 1.0
    return vmax * (1.0 - rho * s / (1.0 + s)) * (un / (1.2 + un)) + c_loc * math.sqrt(max(un, 0.0))

def fit(train_rows):
    rows = list(train_rows)
    y = np.asarray([float(r['y']) for r in rows])
    def residual(p):
        return np.asarray([_model(r, p) for r in rows]) - y
    result = least_squares(residual, x0=np.array([8.0, 0.7, -0.3]), bounds=([0.0, 0.0, -10.0], [100.0, 1.0, 10.0]))
    return result.x

def predict(row):
    return float(_model(row, fit(_TRAIN_ROWS)))
